#include <iostream>

int main() {
    int x = 6;
    int y = 4;

    // Verify De Morgan's Law: !(x < 5) && !(y >= 7) <=> !((x < 5) || (y >= 7))
    bool originalExpr = !(x < 5) && !(y >= 7);
    bool deMorganExpr = !((x < 5) || (y >= 7));
    bool simplifiedExpr = (x >= 5) && (y < 7);

    std::cout << std::boolalpha;
    std::cout << "Original: " << originalExpr << "\n";
    std::cout << "De Morgan: " << deMorganExpr << "\n";
    std::cout << "Simplified: " << simplifiedExpr << "\n";

    // Structured loop replacing both break and continue
    // Goal: print numbers 1 to 5, skipping 2, stopping before 5 without break/continue
    std::cout << "Structured iteration: ";
    bool terminateEarly = false;
    for (int count = 1; count <= 5 && !terminateEarly; ++count) {
        if (count == 4) {
            terminateEarly = true; // structured break equivalent
        } else if (count != 2) {   // structured continue equivalent
            std::cout << count << " ";
        }
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>

int main() {
    // 1. Draw a 5-row diamond using nested loops
    int n = 5;
    int mid = n / 2;

    std::cout << "--- Diamond (height 5) ---\n";
    for (int row = 0; row < n; ++row) {
        int spaces = (row <= mid) ? (mid - row) : (row - mid);
        int stars = n - 2 * spaces;
        for (int s = 0; s < spaces; ++s) {
            std::cout << ' ';
        }
        for (int k = 0; k < stars; ++k) {
            std::cout << '*';
        }
        std::cout << '\n';
    }

    // 2. Find Pythagorean triples with sides <= 20 using brute force
    std::cout << "--- Pythagorean Triples (<= 20) ---\n";
    int limit = 20;
    for (int a = 1; a <= limit; ++a) {
        for (int b = a + 1; b <= limit; ++b) {
            for (int c = b + 1; c <= limit; ++c) {
                if (a * a + b * b == c * c) {
                    std::cout << a << ", " << b << ", " << c << '\n';
                }
            }
        }
    }

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    // 1. Stream radix table demonstration
    int testValue = 255;
    std::cout << "Value " << testValue << " in:\n";
    std::cout << "Decimal: " << std::dec << testValue << "\n";
    std::cout << "Octal:   " << std::oct << testValue << "\n";
    std::cout << "Hex:     " << std::hex << testValue << "\n";

    // Reset back to dec
    std::cout << std::dec;

    // 2. Integer-only compound interest calculation (in cents)
    // Principal = $24.00 = 2400 cents, annual rate = 5%, calculate 3 years
    long long balanceInCents = 2400;
    int ratePercent = 5;

    std::cout << "Year 0: $" << balanceInCents / 100 << "." 
              << std::setfill('0') << std::setw(2) << balanceInCents % 100 << "\n";

    for (int year = 1; year <= 3; ++year) {
        // Interest rounded to nearest cent: (balance * rate + 50) / 100
        long long interest = (balanceInCents * ratePercent + 50) / 100;
        balanceInCents += interest;

        std::cout << "Year " << year << ": $" 
                  << balanceInCents / 100 << "." 
                  << std::setfill('0') << std::setw(2) << balanceInCents % 100 << "\n";
    }

    return 0;
}
